import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 촉진 단계는 1차·2차이며 통보 시기는 법령 및 사내 기준에 따른다 (구체 기준 미제공, 형식만 검사)
const STAGES = ['1차', '2차'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isId(value: unknown): boolean {
  if (typeof value === 'number') {
    return Number.isInteger(value) && value > 0;
  }
  if (typeof value === 'string') {
    return /^\d+$/.test(value);
  }
  return false;
}

function blank(value: unknown): boolean {
  return value === undefined || value === null || value === '';
}

@Controller('api/v1')
export class FnSfr01906Controller {
  @Post('/leave-promotions')
  @HttpCode(200)
  async createLeavePromotion(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    if (blank(data['annualLeaveId']) || blank(data['employeeId']) || blank(data['promotionStage']) || blank(data['noticeDate'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '필수 값이 누락되었습니다.');
    }
    if (!isId(data['annualLeaveId']) || !isId(data['employeeId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연차와 임직원은 숫자 ID여야 합니다.');
    }
    if (typeof data['promotionStage'] !== 'string' || !STAGES.includes(data['promotionStage'])) {
      throw new ApiError(422, 'INVALID_PROMOTION_STAGE', '촉진 단계는 1차 또는 2차여야 합니다.');
    }
    if (typeof data['noticeDate'] !== 'string' || !DATE_PATTERN.test(data['noticeDate'])) {
      throw new ApiError(422, 'INVALID_PROMOTION_STAGE', '통보일은 YYYY-MM-DD 형식이어야 합니다.');
    }
    const params = {
      annualLeaveId: String(data['annualLeaveId']),
      employeeId: String(data['employeeId']),
      promotionStage: data['promotionStage'],
      noticeDate: data['noticeDate'],
    };
    return transaction(async (db) => {
      const leaves = await db.query(
        'SELECT annual_leave_id FROM annual_leave WHERE annual_leave_id = CAST(:annualLeaveId AS bigint) AND employee_id = CAST(:employeeId AS bigint)',
        params,
      );
      if (leaves.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_NOT_FOUND', '대상 임직원의 연차가 생성되어 있지 않습니다.');
      }
      const dup = await db.query(
        'SELECT leave_promotion_id FROM leave_promotion WHERE annual_leave_id = CAST(:annualLeaveId AS bigint) AND promotion_stage = :promotionStage',
        params,
      );
      if (dup.length > 0) {
        throw new ApiError(422, 'INVALID_PROMOTION_STAGE', '이미 해당 단계의 촉진이 등록되어 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO leave_promotion (annual_leave_id, employee_id, promotion_stage, notice_date, created_at, updated_at) '
          + 'VALUES (CAST(:annualLeaveId AS bigint), CAST(:employeeId AS bigint), :promotionStage, CAST(:noticeDate AS date), now(), now()) '
          + 'RETURNING leave_promotion_id AS "leavePromotionId"',
        params,
      );
      return rows[0];
    });
  }

  @Get('/leave-promotions')
  async listLeavePromotions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자', '임직원');
    const q = checks.queryOf(req.query);
    const fromDate = blank(q['fromDate']) ? null : String(q['fromDate']);
    const toDate = blank(q['toDate']) ? null : String(q['toDate']);
    if ((fromDate !== null && !DATE_PATTERN.test(fromDate)) || (toDate !== null && !DATE_PATTERN.test(toDate))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간은 YYYY-MM-DD 형식이어야 합니다.');
    }
    if (!blank(q['departmentId']) && !isId(q['departmentId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '부서 조건은 숫자여야 합니다.');
    }
    const departmentId = blank(q['departmentId']) ? null : String(q['departmentId']);
    const page = blank(q['page']) ? 0 : Number(q['page']);
    const size = blank(q['size']) ? DEFAULT_SIZE : Number(q['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    const where =
      ' FROM leave_promotion lp'
      + ' JOIN annual_leave al ON al.annual_leave_id = lp.annual_leave_id'
      + ' JOIN employee e ON e.employee_id = lp.employee_id'
      + ' WHERE (CAST(:fromDate AS date) IS NULL OR lp.notice_date >= CAST(:fromDate AS date))'
      + ' AND (CAST(:toDate AS date) IS NULL OR lp.notice_date <= CAST(:toDate AS date))'
      + ' AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))';
    const filterParams = { fromDate, toDate, departmentId };
    return transaction(async (db) => {
      const counts = await db.query('SELECT COUNT(*) AS total' + where, filterParams);
      const items = await db.query(
        'SELECT lp.leave_promotion_id AS "leavePromotionId", lp.employee_id AS "employeeId", lp.promotion_stage AS "promotionStage", '
          + 'to_char(lp.notice_date, \'YYYY-MM-DD\') AS "noticeDate", COALESCE(al.used_days, 0) AS "usedDays"'
          + where
          + ' ORDER BY lp.notice_date DESC, lp.leave_promotion_id DESC'
          + ' LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { ...filterParams, limit: String(limit), offset: String(page * limit) },
      );
      return { items, page, size: limit, total: Number(counts[0]['total']) };
    });
  }
}

