import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;
const STAGE_OPTIONS: [string, string][] = [
  ['1차', '1차'],
  ['2차', '2차'],
];

export default function FnSfr01906Page({ role, notify }: PageProps) {
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [drawer, setDrawer] = useState<'' | 'promotion' | 'plan'>('');
  const [form, setForm] = useState<Row>({});

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/leave-promotions', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );
  const rows = data ? data.items : [];
  const stageCount = (stage: string) => rows.filter((r) => r['promotionStage'] === stage).length;

  const set = (key: string, value: unknown) => setForm({ ...form, [key]: value });
  const open = (kind: 'promotion' | 'plan') => {
    setForm({});
    setDrawer(kind);
  };
  const search = () => {
    setPage(0);
    setApplied({ fromDate, toDate, departmentId });
  };
  const reset = () => {
    setFromDate('');
    setToDate('');
    setDepartmentId('');
    setPage(0);
    setApplied({});
  };

  const submitPromotion = async () => {
    if (!form['annualLeaveId'] || !form['employeeId'] || !form['promotionStage'] || !form['noticeDate']) {
      throw new Error('연차, 촉진 대상 임직원, 촉진 단계, 통보일을 모두 입력하세요.');
    }
    await call('POST', '/leave-promotions', role, {
      annualLeaveId: form['annualLeaveId'],
      employeeId: form['employeeId'],
      promotionStage: form['promotionStage'],
      noticeDate: form['noticeDate'],
    });
    notify('연차사용촉진계획을 등록했습니다.');
    setDrawer('');
    reload();
  };

  const submitPlan = async () => {
    if (!form['employeeId'] || !form['planMonth'] || !form['planDate']) {
      throw new Error('임직원, 계획 연월, 계획 일자를 모두 입력하세요.');
    }
    await call('POST', '/annual-leave-plans', role, {
      employeeId: form['employeeId'],
      planMonth: form['planMonth'],
      planDate: form['planDate'],
    });
    notify('월별 연차계획을 등록했습니다.');
    setDrawer('');
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>촉진 현황</h2>
        <Tiles
          items={[
            ['전체 촉진', <Num value={data ? data.total : 0} />],
            ['1차 (현재 쪽)', <Num value={stageCount('1차')} />],
            ['2차 (현재 쪽)', <Num value={stageCount('2차')} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>연차사용촉진</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일">
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          <Field label="부서 조건">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={() => open('plan')}>연차계획 등록</button>
          <button type="button" onClick={() => open('promotion')}>촉진계획 등록</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={rows}
          empty="등록된 연차사용촉진이 없습니다."
          columns={[
            { key: 'employeeId', label: '촉진 대상 임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'promotionStage', label: '촉진 단계', render: (r) => <Badge value={r['promotionStage']} /> },
            { key: 'noticeDate', label: '통보일', render: (r) => <DateText value={r['noticeDate']} /> },
            { key: 'usedDays', label: '사용 일수', render: (r) => <Num value={r['usedDays']} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {drawer === 'promotion' ? (
        <Drawer title="연차사용촉진계획 등록" onClose={() => setDrawer('')}>
          <Form onSubmit={submitPromotion} submit="등록">
            <Field label="연차" required>
              <LookupSelect table="annual_leave" role={role} value={form['annualLeaveId']} onChange={(v) => set('annualLeaveId', v)} />
            </Field>
            <Field label="촉진 대상 임직원" required>
              <LookupSelect table="employee" role={role} value={form['employeeId']} onChange={(v) => set('employeeId', v)} />
            </Field>
            <Field label="촉진 단계" required>
              <Select value={form['promotionStage']} onChange={(v) => set('promotionStage', v)} options={STAGE_OPTIONS} />
            </Field>
            <Field label="통보일" required>
              <DateInput value={form['noticeDate']} onChange={(v) => set('noticeDate', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {drawer === 'plan' ? (
        <Drawer title="월별 연차계획 등록" onClose={() => setDrawer('')}>
          <Form onSubmit={submitPlan} submit="등록">
            <Field label="임직원" required>
              <LookupSelect table="employee" role={role} value={form['employeeId']} onChange={(v) => set('employeeId', v)} />
            </Field>
            <Field label="계획 연월" required hint="YYYY-MM">
              <TextInput value={form['planMonth']} onChange={(v) => set('planMonth', v)} placeholder="2025-01" />
            </Field>
            <Field label="계획 일자" required>
              <DateInput value={form['planDate']} onChange={(v) => set('planDate', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
